sanitized:
# =============================================================================
# Redpanda Connect (Wombat) — declarative data feed engine → NATS → TAK
#
# Runs in streams mode: all pipeline files in /config/pipelines/ run as
# independent concurrent streams in one pod. To add a feed: drop a YAML file
# in pipelines/ and add it to the ConfigMap below.
#
# Current pipelines:
#   feed-mta.yaml      — MTA Metro-North + LIRR trains → tak.cot.inject (30s poll)
#   feed-hazards.yaml  — USGS earthquakes + NWS weather alerts → tak.cot.inject (60s poll)
#   feed-ships.yaml    — AIS vessel positions via aisstream.io WebSocket → tak.cot.inject
#   feed-aircraft.yaml — ADS-B aircraft via OpenSky REST → tak.cot.inject (15s poll)
#
# Secrets required in omos namespace:
#   omos-nats-creds   — NATS_USER, NATS_PASSWORD
#   omos-feed-secrets — AISSTREAM_API_KEY (ships), OPENSKY_USERNAME/PASSWORD (aircraft, optional)
#
# Proto schemas live in platform/redpanda-connect/gtfs-realtime.proto.
# =============================================================================
apiVersion: v1
kind: ConfigMap
metadata:
  name: redpanda-connect-pipelines
  namespace: omos
data:
  feed-mta.yaml: |
    input:
      generate:
        interval: "30s"
        mapping: 'root = ""'

    pipeline:
      processors:
        - branch:
            request_map: 'root = ""'
            processors:
              - http:
                  url: "https://api-endpoint.mta.info/Dataservice/mtagtfsfeeds/mnr%2Fgtfs-mnr"
                  verb: GET
                  timeout: "10s"
                  headers:
                    User-Agent: "OMOS-FeedEngine/1.0"
              - protobuf:
                  operator: to_json
                  message: "transit_realtime.FeedMessage"
                  import_paths: ["/proto/"]
              - mapping: |
                  root = this.entity.filter(e -> e.exists("vehicle") && e.vehicle.exists("position")).map_each(e -> {
                    "uid": "MTA-MNR-%s".format(e.vehicle.trip.trip_id.or(e.id)),
                    "callsign": "MNR-%s".format(e.vehicle.trip.route_id.or(e.vehicle.trip.trip_id.or("?"))),
                    "lat": e.vehicle.position.latitude,
                    "lon": e.vehicle.position.longitude,
                    "speed": e.vehicle.position.speed.or(0),
                    "course": e.vehicle.position.bearing.or(0),
                    "remarks": "MTA Metro-North route:%s trip:%s".format(e.vehicle.trip.route_id.or("?"), e.vehicle.trip.trip_id.or("?")),
                    "feed": "MNR"
                  })
            result_map: 'root.mnr = this'

        - branch:
            request_map: 'root = ""'
            processors:
              - http:
                  url: "https://api-endpoint.mta.info/Dataservice/mtagtfsfeeds/lirr%2Fgtfs-lirr"
                  verb: GET
                  timeout: "10s"
                  headers:
                    User-Agent: "OMOS-FeedEngine/1.0"
              - protobuf:
                  operator: to_json
                  message: "transit_realtime.FeedMessage"
                  import_paths: ["/proto/"]
              - mapping: |
                  root = this.entity.filter(e -> e.exists("vehicle") && e.vehicle.exists("position")).map_each(e -> {
                    "uid": "MTA-LIRR-%s".format(e.vehicle.trip.trip_id.or(e.id)),
                    "callsign": "LIRR-%s".format(e.vehicle.trip.route_id.or(e.vehicle.trip.trip_id.or("?"))),
                    "lat": e.vehicle.position.latitude,
                    "lon": e.vehicle.position.longitude,
                    "speed": e.vehicle.position.speed.or(0),
                    "course": e.vehicle.position.bearing.or(0),
                    "remarks": "MTA LIRR route:%s trip:%s".format(e.vehicle.trip.route_id.or("?"), e.vehicle.trip.trip_id.or("?")),
                    "feed": "LIRR"
                  })
            result_map: 'root.lirr = this'

        - mapping: |
            root = this.mnr.or([]).concat(this.lirr.or([]))

        - unarchive:
            format: json_array

        - mapping: |
            root = if this.lat == 0 || this.lon == 0 { deleted() } else { this }

        - mapping: |
            let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
            let stale = (now().ts_unix() + 120).ts_format("2006-01-02T15:04:05.000Z")
            let cs = this.callsign.replace_all("&", "&amp;").replace_all("<", "&lt;").replace_all("\"", "&quot;")
            root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"a-n-G-E-V-C-R\" uid=\"" + this.uid + "\" how=\"m-g\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"0\" ce=\"50\" le=\"50\"/><detail><contact callsign=\"" + $cs + "\"/><track speed=\"" + this.speed.string() + "\" course=\"" + this.course.string() + "\"/><remarks>" + this.remarks + "</remarks><marti><dest mission=\"Land\"/></marti></detail></event>"

    output:
      nats:
        urls: ["nats://nats.nats.svc.cluster.local:4222"]
        subject: "tak.cot.inject"
        auth:
          user: "${NATS_USER}"
          password: "[REDACTED]"
        tls:
          enabled: true
          skip_cert_verify: true
  feed-hazards.yaml: |
    cache_resources:
      - label: seen_hazards
        memory:
          ttl: 21600s
          cap: 10000

    input:
      generate:
        interval: "60s"
        mapping: 'root = ""'

    pipeline:
      processors:
        - branch:
            request_map: 'root = ""'
            processors:
              - http:
                  url: "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_hour.geojson"
                  verb: GET
                  timeout: "15s"
                  headers:
                    User-Agent: "OMOS-FeedEngine/1.0"
              - mapping: |
                  root = this.features.or([]).map_each(f -> {
                    "id": f.id,
                    "uid": "USGS-" + f.id,
                    "lat": f.geometry.coordinates.index(1),
                    "lon": f.geometry.coordinates.index(0),
                    "depth": f.geometry.coordinates.index(2).or(0),
                    "mag": f.properties.mag.or(0),
                    "place": f.properties.place.or("Unknown").replace_all("&", "&amp;").replace_all("<", "&lt;"),
                    "stale_s": 21600,
                    "hae": (0 - (f.geometry.coordinates.index(2).or(0) * 1000)).round().string(),
                    "source": "USGS"
                  })
            result_map: 'root.usgs = this'

        - branch:
            request_map: 'root = ""'
            processors:
              - http:
                  url: "https://api.weather.gov/alerts/active?severity=Extreme,Severe&status=actual"
                  verb: GET
                  timeout: "15s"
                  headers:
                    Accept: "application/geo+json"
                    User-Agent: "OMOS-FeedEngine/1.0"
              - mapping: |
                  root = this.features.or([]).map_each(f ->
                    let geom = f.geometry.or({})
                    let gtype = $geom.type.or("")
                    let c = if $gtype == "Point" { $geom.coordinates }
                            else if $gtype == "Polygon" { $geom.coordinates.index(0).index(0) }
                            else { null }
                    if $c == null { deleted() } else {
                      let fid = f.id.or("")
                      let short_id = if $fid.length() > 16 { $fid.slice($fid.length() - 16) } else { $fid }
                      {
                        "id": $fid,
                        "uid": "NWS-" + $short_id,
                        "lat": $c.index(1),
                        "lon": $c.index(0),
                        "event": f.properties.event.or("Alert").replace_all("&", "&amp;").replace_all("<", "&lt;"),
                        "headline": (f.properties.headline.or(f.properties.event.or("Alert"))).slice(0, 80).replace_all("&", "&amp;").replace_all("<", "&lt;"),
                        "severity": f.properties.severity.or("Unknown"),
                        "stale_s": 3600,
                        "hae": "9999999.0",
                        "source": "NWS"
                      }
                    }
                  )
            result_map: 'root.nws = this'

        - mapping: |
            root = this.usgs.or([]).concat(this.nws.or([]))

        - unarchive:
            format: json_array

        - dedupe:
            cache: seen_hazards
            key: '${!this.id}'

        - mapping: |
            let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
            let stale = (now().ts_unix() + this.stale_s.number()).ts_format("2006-01-02T15:04:05.000Z")
            let callsign = if this.source == "USGS" {
              "M" + this.mag.format_number(1) + " Earthquake"
            } else {
              this.event
            }
            let remarks = if this.source == "USGS" {
              "M" + this.mag.format_number(1) + " " + this.place + " depth:" + this.depth.format_number(1) + "km"
            } else {
              this.severity + ": " + this.headline
            }
            root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"b-r-f-h-h\" uid=\"" + this.uid + "\" how=\"h-e\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"" + this.hae + "\" ce=\"9999999.0\" le=\"9999999.0\"/><detail><contact callsign=\"" + $callsign + "\"/><status readiness=\"false\"/><remarks>" + $remarks + "</remarks><marti><dest mission=\"Hazards\"/></marti></detail></event>"

    output:
      nats:
        urls: ["nats://nats.nats.svc.cluster.local:4222"]
        subject: "tak.cot.inject"
        auth:
          user: "${NATS_USER}"
          password: "[REDACTED]"
        tls:
          enabled: true
          skip_cert_verify: true
  feed-ships.yaml: |
    input:
      websocket:
        url: "wss://stream.aisstream.io/v0/stream"
        open_message: '{"APIKey": "${AISSTREAM_API_KEY}", "BoundingBoxes": [[[-90, -180], [90, 180]]]}'
        open_message_type: text
        tls:
          enabled: true

    pipeline:
      processors:
        - mapping: |
            let md = this.MetaData.or({})
            let mmsi = $md.MMSI.or($md.UserID)
            let lat = $md.latitude.or($md.Latitude)
            let lon = $md.longitude.or($md.Longitude)
            root = if $mmsi == null || $lat == null || $lon == null { deleted() } else {
              let pr = this.Message.or({})
              let pos = $pr.PositionReport.or($pr.StandardClassBPositionReport.or({}))
              let sog = $pos.Sog.or(0)
              let cog = $pos.Cog.or(0)
              let sdata = $pr.ShipStaticData.or({})
              let ship_name = $sdata.Name.or($md.ShipName.or("")).string().trim()
              let cs = if $ship_name == "" { $mmsi.string() } else { $ship_name.slice(0, 32).replace_all("&", "&amp;").replace_all("<", "&lt;").replace_all("\"", "&quot;") }
              let stype = $sdata.Type.Code.or("").string()
              {
                "uid": "AIS-" + $mmsi.string(),
                "callsign": $cs,
                "lat": $lat,
                "lon": $lon,
                "sog": $sog,
                "cog": $cog,
                "mmsi": $mmsi,
                "stype": $stype
              }
            }

        - mapping: |
            let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
            let stale = (now().ts_unix() + 300).ts_format("2006-01-02T15:04:05.000Z")
            root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"a-f-S-X-M\" uid=\"" + this.uid + "\" how=\"m-g\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"-10000\" ce=\"9999999.0\" le=\"9999999.0\"/><detail><contact callsign=\"" + this.callsign + "\"/><track speed=\"" + this.sog.string() + "\" course=\"" + this.cog.string() + "\"/><status readiness=\"false\"/><remarks>MMSI:" + this.mmsi.string() + " " + this.stype + "</remarks><marti><dest mission=\"Sea\"/></marti></detail></event>"

    output:
      nats:
        urls: ["nats://nats.nats.svc.cluster.local:4222"]
        subject: "tak.cot.inject"
        auth:
          user: "${NATS_USER}"
          password: "[REDACTED]"
        tls:
          enabled: true
          skip_cert_verify: true
  feed-aircraft.yaml: |
    input:
      generate:
        interval: "15s"
        mapping: 'root = ""'

    pipeline:
      processors:
        - branch:
            request_map: 'root = ""'
            processors:
              - http:
                  url: "https://opensky-network.org/api/states/all"
                  verb: GET
                  timeout: "20s"
                  headers:
                    User-Agent: "omos-feed-aircraft/1.0"
              - mapping: |
                  root = this.states.or([]).map_each(s ->
                    let lon = s.index(5)
                    let lat = s.index(6)
                    if $lon == null || $lat == null { deleted() } else {
                      let icao24 = s.index(0).or("").string()
                      let raw_cs = s.index(1).or("").string().trim()
                      let callsign = if $raw_cs == "" { $icao24.uppercase() } else { $raw_cs.replace_all("&", "&amp;").replace_all("<", "&lt;").replace_all("\"", "&quot;") }
                      let alt = s.index(7).or(0)
                      let spd_kt = s.index(9).or(0) * 1.94384
                      let trk = s.index(10).or(0)
                      let country = s.index(2).or("").string().replace_all("&", "&amp;").replace_all("<", "&lt;")
                      {
                        "uid": "ADSB-" + $icao24.uppercase(),
                        "callsign": $callsign,
                        "lat": $lat,
                        "lon": $lon,
                        "alt": $alt,
                        "spd_kt": $spd_kt,
                        "trk": $trk,
                        "icao24": $icao24,
                        "country": $country
                      }
                    }
                  )
            result_map: 'root = this'

        - unarchive:
            format: json_array

        - mapping: |
            let ts = now().format_timestamp("2006-01-02T15:04:05.000Z")
            let stale = (now().ts_unix() + 90).ts_format("2006-01-02T15:04:05.000Z")
            root = "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\" ?>\n<event version=\"2.0\" type=\"a-f-A-M-F-Q\" uid=\"" + this.uid + "\" how=\"m-g\" time=\"" + $ts + "\" start=\"" + $ts + "\" stale=\"" + $stale + "\"><point lat=\"" + this.lat.string() + "\" lon=\"" + this.lon.string() + "\" hae=\"" + this.alt.string() + "\" ce=\"9999999.0\" le=\"9999999.0\"/><detail><contact callsign=\"" + this.callsign + "\"/><track speed=\"" + this.spd_kt.format_number(1) + "\" course=\"" + this.trk.string() + "\"/><status readiness=\"false\"/><remarks>ICAO:" + this.icao24 + " " + this.country + "</remarks><marti><dest mission=\"Air\"/></marti></detail></event>"

    output:
      nats:
        urls: ["nats://nats.nats.svc.cluster.local:4222"]
        subject: "tak.cot.inject"
        auth:
          user: "${NATS_USER}"
          password: "[REDACTED]"
        tls:
          enabled: true
          skip_cert_verify: true
